@if($tab === 'regions')
<div class="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
    <div><label class="mb-2 block text-xs font-extrabold uppercase tracking-wide text-slate-600">Status</label><select x-model="regionStatusFilter" class="w-full rounded-xl border-2 border-slate-200 bg-white px-3 py-3 text-sm font-semibold text-slate-900 outline-none focus:border-orange-400 focus:ring-4 focus:ring-orange-100"><option value="">All statuses</option><option value="active">Active</option><option value="inactive">Inactive</option></select></div>
    <div><label class="mb-2 block text-xs font-extrabold uppercase tracking-wide text-slate-600">Region Code</label><input type="text" x-model="regionCodeFilter" placeholder="Search code..." class="w-full rounded-xl border-2 border-slate-200 bg-white px-3 py-3 text-sm font-semibold text-slate-900 outline-none placeholder:text-slate-400 focus:border-orange-400 focus:ring-4 focus:ring-orange-100"></div>
    <div><label class="mb-2 block text-xs font-extrabold uppercase tracking-wide text-slate-600">Coverage</label><select x-model="regionCoverageFilter" class="w-full rounded-xl border-2 border-slate-200 bg-white px-3 py-3 text-sm font-semibold text-slate-900 outline-none focus:border-orange-400 focus:ring-4 focus:ring-orange-100"><option value="">Any coverage</option><option value="has_districts">Has districts</option><option value="no_districts">No districts</option><option value="has_towns">Has towns</option><option value="no_towns">No towns</option><option value="has_active_towns">Has active towns</option><option value="no_active_towns">No active towns</option></select></div>
    <div><label class="mb-2 block text-xs font-extrabold uppercase tracking-wide text-slate-600">District Count</label><div class="grid grid-cols-2 overflow-hidden rounded-xl border-2 border-slate-200 bg-white focus-within:border-orange-400 focus-within:ring-4 focus-within:ring-orange-100"><input type="number" min="0" x-model="regionDistrictsMin" placeholder="Min" class="min-w-0 border-0 px-3 py-3 text-sm font-semibold text-slate-900 outline-none"><input type="number" min="0" x-model="regionDistrictsMax" placeholder="Max" class="min-w-0 border-0 border-l border-slate-200 px-3 py-3 text-sm font-semibold text-slate-900 outline-none"></div></div>
