</div>
<div class="mt-4 flex flex-wrap items-center justify-end gap-3 border-t border-slate-200 pt-4"><button type="button" @click="showRegionFilters = false" class="mr-auto rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-bold text-slate-700 transition hover:bg-slate-50">Close Filters</button><button type="button" @click="clearRegionFilters()" class="rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-bold text-slate-700 transition hover:bg-slate-50">Clear Filters</button><button type="button" @click="applyRegionFilters()" class="rounded-xl bg-orange-600 px-5 py-3 text-sm font-bold text-white shadow-lg shadow-orange-600/20 transition hover:bg-orange-700">Apply Filters</button></div>
@elseif($tab === 'districts')
