    <div><label class="mb-2 block text-xs font-extrabold uppercase tracking-wide text-slate-600">Town Coverage</label><select x-model="districtCoverageFilter" class="w-full rounded-xl border-2 border-slate-200 bg-white px-3 py-3 text-sm font-semibold text-slate-900 outline-none focus:border-orange-400 focus:ring-4 focus:ring-orange-100"><option value="">Any coverage</option><option value="has_towns">Has towns</option><option value="no_towns">No towns</option><option value="has_active_towns">Has active towns</option><option value="no_active_towns">No active towns</option></select></div>
    <div><label class="mb-2 block text-xs font-extrabold uppercase tracking-wide text-slate-600">Town Count</label><div class="grid grid-cols-2 overflow-hidden rounded-xl border-2 border-slate-200 bg-white focus-within:border-orange-400 focus-within:ring-4 focus-within:ring-orange-100"><input type="number" min="0" x-model="districtTownsMin" placeholder="Min" class="min-w-0 border-0 px-3 py-3 text-sm font-semibold text-slate-900 outline-none"><input type="number" min="0" x-model="districtTownsMax" placeholder="Max" class="min-w-0 border-0 border-l border-slate-200 px-3 py-3 text-sm font-semibold text-slate-900 outline-none"></div></div>
