    <div><label class="mb-2 block text-xs font-extrabold uppercase tracking-wide text-slate-600">District</label><select x-model="townDistrictFilter" class="w-full rounded-xl border-2 border-slate-200 bg-white px-3 py-3 text-sm font-semibold text-slate-900 outline-none focus:border-orange-400 focus:ring-4 focus:ring-orange-100"><option value="">All districts</option><template x-for="d in townFilterDistricts" :key="d.id"><option :value="d.id" x-text="d.name"></option></template></select></div>
