    <div><label class="mb-2 block text-xs font-extrabold uppercase tracking-wide text-slate-600">Region Status</label><select x-model="townRegionStatusFilter" class="w-full rounded-xl border-2 border-slate-200 bg-white px-3 py-3 text-sm font-semibold text-slate-900 outline-none focus:border-orange-400 focus:ring-4 focus:ring-orange-100"><option value="">Any region</option><option value="active">Active region</option><option value="inactive">Inactive region</option></select></div>
    <div><label class="mb-2 block text-xs font-extrabold uppercase tracking-wide text-slate-600">District Status</label><select x-model="townDistrictStatusFilter" class="w-full rounded-xl border-2 border-slate-200 bg-white px-3 py-3 text-sm font-semibold text-slate-900 outline-none focus:border-orange-400 focus:ring-4 focus:ring-orange-100"><option value="">Any district</option><option value="active">Active district</option><option value="inactive">Inactive district</option></select></div>
    <div><label class="mb-2 block text-xs font-extrabold uppercase tracking-wide text-slate-600">Route Health</label><select x-model="townParentStateFilter" class="w-full rounded-xl border-2 border-slate-200 bg-white px-3 py-3 text-sm font-semibold text-slate-900 outline-none focus:border-orange-400 focus:ring-4 focus:ring-orange-100"><option value="">Any route health</option><option value="ready">Active region + district</option><option value="inactive_region">Inactive region</option><option value="inactive_district">Inactive district</option></select></div>
